use super::*;

/// `bsc session mode [local|claude] [--project <key>]` — report or switch a project's environment.
///
/// # It dispatches HERE rather than through the router
///
/// The inspection sub-nouns above (`perms`, `skills`, `mcp`, `argv`) are advertised by this crate and
/// routed by the `bsc` binary, so that `bsc-session` takes no dependency on the three surfaces behind
/// them. `mode` needs none of that: the whole implementation is `bsc_cli_util::session_mode`, and
/// this crate already depends on `bsc-cli-util`. Routing it would add an indirection to keep a
/// dependency that already exists.
pub fn cmd_mode(args: &Args) -> Result<(), String> {
    let key = args
        .positional
        .iter()
        .skip(1)
        .find(|p| !bsc_cli_util::session_mode::is_mode(p))
        .cloned()
        .or_else(|| std::env::var("BSC_PROJECT_KEY").ok().filter(|v| !v.trim().is_empty()))
        .ok_or(
            "no project — pass `--project <key>` or run where $BSC_PROJECT_KEY is set.\n\
             usage: bsc session mode [local|claude] [--project <key>]",
        )?;
    let base = bsc_util::bsc_base_dir().ok_or("could not resolve a home directory; set HOME/USERPROFILE")?;
    let hub = base.join("projects").join(&key);
    if !hub.is_dir() {
        return Err(format!("no project hub at {} — is '{key}' the right project key?", hub.display()));
    }

    let wanted = args.positional.iter().skip(1).find(|p| bsc_cli_util::session_mode::is_mode(p));
    match wanted {
        // REPORT. The chain already tracks where each value came from, so this says whether the
        // project is in a mode BECAUSE someone set it or because it inherited the machine default —
        // which is the difference between "this project is local" and "nothing has decided yet".
        None => {
            let r = bsc_cli_util::session::resolve(&hub);
            let mode = bsc_cli_util::session_mode::mode_of(&r);
            if args.json {
                // Built OUTSIDE the macro: `json!` cannot parse a method chain in value position.
                let fields: Vec<serde_json::Value> = ["provider", "model", "baseUrl", "numCtx"]
                    .iter()
                    .map(|f| {
                        serde_json::json!({
                            "field": f,
                            "value": r.get(f),
                            "from": r.source_of(f).map(bsc_cli_util::session::Source::describe),
                        })
                    })
                    .collect();
                let v = serde_json::json!({
                    "project": key,
                    "mode": mode,
                    "hub": hub.display().to_string(),
                    "fields": fields,
                });
                bsc_util::emit_line(&serde_json::to_string(&v).unwrap_or_default());
                return Ok(());
            }
            println!("{key}: {}", mode.unwrap_or("neither local nor claude"));
            for f in ["provider", "model", "baseUrl", "numCtx"] {
                match (r.get(f), r.source_of(f)) {
                    (Some(v), Some(s)) => println!("  {f:<9} {v:<28} from {}", s.describe()),
                    (Some(v), None) => println!("  {f:<9} {v}"),
                    (None, _) => println!("  {f:<9} (unset)"),
                }
            }
            Ok(())
        }
        Some(m) => {
            let d = bsc_cli_util::session_mode::mode_defaults()?;
            let path = bsc_cli_util::session_mode::write_hub_mode(&hub, m, &d)?;
            if args.json {
                let v = serde_json::json!({ "project": key, "mode": m, "wrote": path.display().to_string() });
                bsc_util::emit_line(&serde_json::to_string(&v).unwrap_or_default());
            } else {
                println!("{key} → {m}");
                println!("  wrote {}", path.display());
                println!(
                    "  A session already running keeps the environment it launched with — restart it to pick this up."
                );
            }
            Ok(())
        }
    }
}
